namespace App\Elephentity\Author;

use App\Elephentity\Comment\Comment;
use Eleph\Runtime\Identity\EntityId;
use Eleph\Runtime\Query\EdgeLoader;
use Eleph\Runtime\Query\EntityQuery;

/**
 * Someone who writes comments.
 */
final class Author
{
    private function __construct(
        private readonly EntityId $id,
        private readonly EdgeLoader $edges,
        private readonly string $name,
    ) {

    }

    public function getId(): EntityId {
        return $this->id;
    }

    public function getName(): string {
        return $this->name;
    }

    /**
     * Every Comment whose "author" points here.
     *
     * @return EntityQuery<Comment>
     */
    public function comments(): EntityQuery {
        /** @var EntityQuery<Comment> $related */
        $related = $this->edges->inverseToMany('Comment', 'author', $this->id);

        return $related;
    }

    public static function of(
        EntityId $id,
        EdgeLoader $edges,
        string $name,
    ): self {
        return new self($id, $edges, $name);
    }
}

namespace App\Elephentity\Author;

use Eleph\Runtime\Identity\EntityId;
use Eleph\Runtime\Mutation\Deletion;
use Eleph\Runtime\Storage\DeletionPolicy;
use Eleph\Runtime\Storage\DeletionRule;
use Eleph\Runtime\UnitOfWork\UnitOfWork;

/**
 * Removes a Author, and whatever its edges say goes with it.
 */
final class AuthorDeleter
{
    public function __construct(
        private readonly UnitOfWork $work,
    ) {

    }

    /**
     * Registers the removal. Nothing happens until the unit of work commits.
     */
    public function delete(
        EntityId $id,
    ): void {
        $this->work->delete(new Deletion('Author', $id));
    }

    /**
     * @return list<DeletionRule>
     */
    public static function rules(): array {
        return [
            new DeletionRule('Comment', 'author', 'Comment', DeletionPolicy::Nullify, false),
        ];
    }
}

namespace App\Elephentity\Author;

use Eleph\Runtime\Query\EdgeLoader;
use Eleph\Runtime\Query\Hydrator;
use Eleph\Runtime\Query\ValueDecoder;
use Eleph\Runtime\Storage\Record;

/**
 * Builds a Author from a stored row.
 *
 * @implements Hydrator<Author>
 */
final readonly class AuthorHydrator implements Hydrator
{
    public function __construct(
        private ValueDecoder $decode,
    ) {

    }

    public function hydrate(
        Record $record,
        EdgeLoader $edges,
    ): Author {
        return Author::of(
            $record->id,
            $edges,
            $this->name($record),
        );
    }

    private function name(
        Record $record,
    ): string {
        $value = $record->value('name');

        return $this->decode->string($value, 'Author.name');
    }
}

namespace App\Elephentity\Author;

use Eleph\Runtime\Mutation\MutationBuffer;
use Eleph\Runtime\Query\ValueDecoder;
use InvalidArgumentException;

/**
 * Turns raw input into pending Author changes.
 */
final readonly class AuthorInput
{
    public function __construct(
        private ValueDecoder $decode,
    ) {

    }

    private function name(
        mixed $value,
    ): ?string {
        if (null === $value) {
            return null;
        }

        return $this->decode->string($value, 'Author.name');
    }

    /**
     * Seeds declared defaults on create and applies explicit input.
     * Absent update keys and existing pending values are not reset by defaults.
     *
     * @param array<string, mixed> $input
     */
    public function apply(
        MutationBuffer $buffer,
        array $input,
    ): void {
        if (array_key_exists('name', $input)) {
            $buffer->set('name', $this->name($input['name']));
        }
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    public function decodeAction(
        string $action,
        array $args,
    ): array {
        return match ($action) {

            default => throw new InvalidArgumentException(sprintf('Unknown action %s.', $action)),
        };
    }
}

namespace App\Elephentity\Author;

use Eleph\Runtime\Identity\Identifier;
use Eleph\Runtime\Mutation\ActionCall;
use Eleph\Runtime\Mutation\MutationContext;

/**
 * A pending Author mutation, with exact types.
 */
final readonly class AuthorMutationContext implements MutationContext
{
    private function __construct(
        private MutationContext $context,
    ) {

    }

    /**
     * @return list<ActionCall>
     */
    public function actions(): array {
        return $this->context->actions();
    }

    public function originalEntity(): ?object {
        return $this->context->originalEntity();
    }

    public function id(): Identifier {
        return $this->context->id();
    }

    public function entity(): string {
        return $this->context->entity();
    }

    public function isCreate(): bool {
        return $this->context->isCreate();
    }

    public function original(
        string $field,
    ): mixed {
        return $this->context->original($field);
    }

    public function pending(
        string $field,
    ): mixed {
        return $this->context->pending($field);
    }

    public function isChanged(
        string $field,
    ): bool {
        return $this->context->isChanged($field);
    }

    /**
     * @return array<string, mixed>
     */
    public function changes(): array {
        return $this->context->changes();
    }

    /**
     * @return list<Identifier>
     */
    public function pendingEdge(
        string $edge,
    ): array {
        return $this->context->pendingEdge($edge);
    }

    public function isEdgeChanged(
        string $edge,
    ): bool {
        return $this->context->isEdgeChanged($edge);
    }

    public function originalName(): ?string {
        $value = $this->context->original('name');
        assert(null === $value || is_string($value));

        return $value;
    }

    public function pendingName(): ?string {
        $value = $this->context->pending('name');
        assert(null === $value || is_string($value));

        return $value;
    }

    public static function of(
        MutationContext $context,
    ): self {
        return new self($context);
    }
}

namespace App\Elephentity\Author;

