use Eleph\Runtime\Storage\Record;

/**
 * Builds a Post from a stored row.
 *
 * @implements Hydrator<Post>
 */
final readonly class PostHydrator implements Hydrator
{
    public function __construct(
        private ValueDecoder $decode,
        private MoneyReadProcessor $moneyReader,
    ) {

    }

    public function hydrate(
        Record $record,
        EdgeLoader $edges,
    ): Post {
        return Post::of(
            $record->id,
            $edges,
            $this->createdAt($record),
            $this->updatedAt($record),
            $this->postId($record),
            $this->slug($record),
            $this->title($record),
            $this->price($record),
            $this->status($record),
            $this->visibility($record),
            $this->publishedAt($record),
        );
    }

    private function createdAt(
        Record $record,
    ): DateTimeImmutable {
        $value = $record->value('createdAt');

        return $this->decode->datetime($value, 'Post.createdAt');
    }

    private function updatedAt(
        Record $record,
    ): DateTimeImmutable {
        $value = $record->value('updatedAt');

        return $this->decode->datetime($value, 'Post.updatedAt');
    }

    private function postId(
        Record $record,
    ): ?int {
        $value = $record->value('postId');

        return null === $value ? null : $this->decode->int($value, 'Post.postId');
    }

    private function slug(
        Record $record,
    ): string {
        $value = $record->value('slug');

        return $this->decode->string($value, 'Post.slug');
    }

    private function title(
        Record $record,
    ): string {
        $value = $record->value('title');

        return $this->decode->string($value, 'Post.title');
    }

    private function price(
        Record $record,
    ): ?Money {
        $value = $record->value('price');

        return null === $value ? null : $this->moneyReader->read($this->decode->int($value, 'Post.price'));
    }

    private function status(
        Record $record,
    ): PostStatus {
