namespace App\Elephentity\Post;

use App\Elephentity\Enum\PostStatus;
use App\Elephentity\Enum\PostVisibility;
use App\Elephentity\Type\MoneyReadProcessor;
use App\Type\Money;
use DateTimeImmutable;
use Eleph\Runtime\Identity\Identifier;
use Eleph\Runtime\Mutation\MutationBuffer;
use Eleph\Runtime\Query\ValueDecoder;
use InvalidArgumentException;

/**
 * Turns raw input into pending Post changes.
 */
final readonly class PostInput
{
    public function __construct(
        private ValueDecoder $decode,
        private MoneyReadProcessor $moneyReader,
    ) {

    }

    private function postId(
        mixed $value,
    ): ?int {
        if (null === $value) {
            return null;
        }

        return $this->decode->int($value, 'Post.postId');
    }

    private function slug(
        mixed $value,
    ): ?string {
        if (null === $value) {
            return null;
        }

        return $this->decode->string($value, 'Post.slug');
    }

    private function title(
        mixed $value,
    ): ?string {
        if (null === $value) {
            return null;
        }

        return $this->decode->string($value, 'Post.title');
    }

    private function price(
        mixed $value,
    ): ?Money {
        if (null === $value) {
            return null;
        }

        return $this->moneyReader->read($this->decode->int($value, 'Post.price'));
    }

    private function status(
        mixed $value,
    ): ?PostStatus {
        if (null === $value) {
            return null;
        }

        return $this->decode->enum(PostStatus::class, $value, 'Post.status');
    }

    private function visibility(
        mixed $value,
    ): ?PostVisibility {
        if (null === $value) {
            return null;
        }

        return $this->decode->enum(PostVisibility::class, $value, 'Post.visibility');
    }

    private function publishedAt(
        mixed $value,
    ): ?DateTimeImmutable {
        if (null === $value) {
            return null;
        }

        return $this->decode->datetime($value, 'Post.publishedAt');
    }

    /**
     * @return list<Identifier>
     */
    private function comments(
        mixed $value,
    ): array {
        if (null === $value) {
            return [];
        }

        if (!is_array($value)) {
            throw new InvalidArgumentException(sprintf('%s takes a list of ids.', 'Post.comments'));
        }

        $ids = [];

        foreach ($value as $id) {
            $ids[] = $this->decode->id($id, 'Post.comments');
        }

        return $ids;
    }

    /**
     * @return list<Identifier>
     */
    private function tags(
        mixed $value,
    ): array {
        if (null === $value) {
            return [];
        }

        if (!is_array($value)) {
            throw new InvalidArgumentException(sprintf('%s takes a list of ids.', 'Post.tags'));
        }

        $ids = [];

        foreach ($value as $id) {
            $ids[] = $this->decode->id($id, 'Post.tags');
        }

        return $ids;
    }

    /**
     * Seeds declared defaults on create and applies explicit input.
     * Absent update keys and existing pending values are not reset by defaults.
     *
     * @param array<string, mixed> $input
     */
    public function apply(
        MutationBuffer $buffer,
        array $input,
    ): void {
        if (array_key_exists('postId', $input)) {
            $buffer->set('postId', $this->postId($input['postId']));
        }

        if (array_key_exists('slug', $input)) {
            $buffer->set('slug', $this->slug($input['slug']));
        }

        if (array_key_exists('title', $input)) {
            $buffer->set('title', $this->title($input['title']));
        }

        if (array_key_exists('price', $input)) {
            $buffer->set('price', $this->price($input['price']));
        }

        if (array_key_exists('status', $input)) {
            $buffer->set('status', $this->status($input['status']));
        }

        if (array_key_exists('visibility', $input)) {
            $buffer->set('visibility', $this->visibility($input['visibility']));
        }

        if (array_key_exists('publishedAt', $input)) {
            $buffer->set('publishedAt', $this->publishedAt($input['publishedAt']));
        }

        if (array_key_exists('comments', $input)) {
            $buffer->edge('comments')->set($this->comments($input['comments']));
        }

        if (array_key_exists('tags', $input)) {
            $buffer->edge('tags')->set($this->tags($input['tags']));
        }
    }

    /**
     * @param array<string, mixed> $args
     * @return array<string, mixed>
     */
    public function decodeAction(
        string $action,
        array $args,
    ): array {
        return match ($action) {
            'publish' => ['at' => null === $args['at'] ? null : $this->decode->datetime($args['at'], 'Post.publish.at')],
            default => throw new InvalidArgumentException(sprintf('Unknown action %s.', $action)),
        };
    }
}

