namespace App\Elephentity\Post;

use App\Elephentity\Pattern\Auditable\Contract\AuditableOwnerReadPolicy;
use App\Elephentity\Post\Contract\PostReporterReadPolicy;
use Eleph\Runtime\Policy\EntityReadPolicies;
use Eleph\Runtime\Policy\PolicyDecision;
use Eleph\Runtime\Policy\PolicyOutcome;
use Eleph\Runtime\Policy\Viewer;

final readonly class PostReadPolicies implements EntityReadPolicies
{
    public function __construct(
        private AuditableOwnerReadPolicy $ownerPolicy,
        private PostReporterReadPolicy $reporterPolicy,
    ) {

    }

    public function isEmpty(): bool {
        return false;
    }

    public function decide(
        object $entity,
        Viewer $viewer,
    ): PolicyDecision {
        assert($entity instanceof Post);
        $decision = $this->ownerPolicy->decide($entity, $viewer);
        if (PolicyOutcome::Skip !== $decision->outcome) {
            return $decision->withPolicy('owner');
        }

        $decision = $this->reporterPolicy->decide($entity, $viewer);
        if (PolicyOutcome::Skip !== $decision->outcome) {
            return $decision->withPolicy('reporter');
        }

        return PolicyDecision::allow('')->withPolicy('terminal');
    }
}

namespace App\Elephentity\Post;

use App\Elephentity\Post\Contract\PostAuditSideEffect;
use App\Elephentity\Post\Contract\PostReindexSideEffect;
use Eleph\Runtime\Mutation\EntitySideEffects;
use Eleph\Runtime\Mutation\MutableMutationContext;
use Eleph\Runtime\SideEffect\SideEffectEvent;
use Eleph\Runtime\SideEffect\SideEffectPhase;

/**
 * Runs Post's sideEffects, in the order the spec declares them.
 */
final readonly class PostSideEffects implements EntitySideEffects
{
    public function __construct(
        private PostAuditSideEffect $auditSideEffect,
        private PostReindexSideEffect $reindexSideEffect,
    ) {

    }

    /**
     * @return iterable<callable(): void>
     */
    public function handlers(
        SideEffectPhase $phase,
        SideEffectEvent $event,
        MutableMutationContext $context,
    ): iterable {
        $handlers = [];
        if (SideEffectPhase::PostCommit === $phase && in_array($event, [SideEffectEvent::Create, SideEffectEvent::Update], true)) {
            $handlers[] = fn () => $this->auditSideEffect->handle(PostMutationContext::of($context));
        }

        if (SideEffectPhase::PostCommit === $phase && in_array($event, [SideEffectEvent::Create, SideEffectEvent::Update], true)) {
            $handlers[] = fn () => $this->reindexSideEffect->handle(PostMutationContext::of($context));
        }

        return $handlers;
    }
}

