namespace App\Elephentity\Post;

use App\Elephentity\Post\Contract\PostNoBackwardsWritePolicy;
use Eleph\Runtime\Policy\EntityWritePolicies;
use Eleph\Runtime\Policy\PolicyDecision;
use Eleph\Runtime\Policy\PolicyOutcome;
use Eleph\Runtime\Policy\Viewer;
use Eleph\Runtime\Policy\WriteContext;

final readonly class PostWritePolicies implements EntityWritePolicies
{
    public function __construct(
        private PostNoBackwardsWritePolicy $noBackwardsPolicy,
    ) {

    }

    public function isEmpty(): bool {
        return false;
    }

    public function decide(
        ?object $entity,
        WriteContext $context,
        Viewer $viewer,
    ): PolicyDecision {
        assert(null === $entity || $entity instanceof Post);
        $decision = $this->noBackwardsPolicy->decide($entity, PostWriteContext::of($context), $viewer);
        if (PolicyOutcome::Skip !== $decision->outcome) {
            return $decision->withPolicy('noBackwards');
        }

        return PolicyDecision::deny('No policy allowed this write.')->withPolicy('terminal');
    }
}

namespace App\Elephentity\Tag;

use App\Elephentity\Post\Post;
