use Eleph\Runtime\Query\EntityQuery;

/**
 * Tag, as stored.
 */
final class Tag
{
    private function __construct(
        private readonly EntityId $id,
        private readonly EdgeLoader $edges,
        private readonly string $label,
    ) {

    }

    public function getId(): EntityId {
        return $this->id;
    }

    public function getLabel(): string {
        return $this->label;
    }

    /**
     * Every Post whose "tags" points here.
     *
     * @return EntityQuery<Post>
     */
    public function posts(): EntityQuery {
        /** @var EntityQuery<Post> $related */
        $related = $this->edges->inverseToMany('Post', 'tags', $this->id);

        return $related;
    }

    public static function of(
        EntityId $id,
        EdgeLoader $edges,
        string $label,
    ): self {
        return new self($id, $edges, $label);
    }
}

